use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (c: Vec<f32>)
    ensures
        c@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> c@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> c@[a@.len() + j] == b@[j],
{
    let a_len = a.len();
    let b_len = b.len();

    let mut c: Vec<f32> = Vec::new();

    // Push all elements of a
    let mut i: usize = 0;
    while i < a_len
        invariant
            i <= a_len,
            c@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> c@[k] == a@[k],
        decreases a_len - i,
    {
        c.push(a[i]);
        i += 1;
    }

    // Push all elements of b
    let mut j: usize = 0;
    while j < b_len
        invariant
            j <= b_len,
            c@.len() == a@.len() + j as int,
            forall|k: int| 0 <= k < a@.len() ==> c@[k] == a@[k],
            forall|t: int| 0 <= t < j as int ==> c@[a@.len() + t] == b@[t],
        decreases b_len - j,
    {
        c.push(b[j]);
        j += 1;
    }

    c
}

} // verus!

